function validate([nums1, nums2]) {
  if (nums1.length < 1 || nums1.length > 500) return 'nums1 needs 1 to 500 values.';
  if (nums2.length < 1 || nums2.length > 500) return 'nums2 needs 1 to 500 values.';
  if ([...nums1, ...nums2].some(v => v < -1000 || v > 1000)) return 'Each value is between -1000 and 1000.';
  return null;
}

