function maxDotProduct(nums1, nums2) {
  const m = nums1.length;
  const n = nums2.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(-Infinity));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const product = nums1[i - 1] * nums2[j - 1];
      const extend = Math.max(product, dp[i - 1][j - 1] + product);
      const skip = Math.max(dp[i - 1][j], dp[i][j - 1]);
      dp[i][j] = Math.max(extend, skip);
    }
  }
  return dp[m][n];
}

