function maxDotProduct(nums1, nums2) {
  // Try every pair of non-empty subsequences with equal length.
  const subsequences = arr => {
    const all = [];
    for (let mask = 1; mask < (1 << arr.length); mask++) {
      all.push(arr.filter((_, k) => (mask >> k) & 1));
    }
    return all;
  };
  const rights = subsequences(nums2);
  let best = null;
  for (const a of subsequences(nums1)) {
    for (const b of rights) {
      if (a.length !== b.length) continue;
      let dot = 0;
      for (let k = 0; k < a.length; k++) dot += a[k] * b[k];
      if (best === null || dot > best) best = dot;
    }
  }
  return best;
}

