function generate(rand, size) {
  const large = size === 'large';
  const length = () => large ? 500 : 1 + Math.floor(rand() * 6);
  const span = large ? 1000 : [3, 10, 1000][Math.floor(rand() * 3)];
  const sign = () => { const r = rand(); return r < 0.25 ? -1 : r < 0.5 ? 1 : 0; };
  const make = (len, s) => Array.from({ length: len }, () => {
    const v = Math.floor(rand() * (span + 1));
    return s === 0 ? Math.floor(rand() * (2 * span + 1)) - span : s * v;
  });
  // Sometimes one array is all negative and the other all non-negative, so every product is at most 0.
  const s1 = sign(), s2 = s1 !== 0 && rand() < 0.6 ? -s1 : sign();
  return [make(length(), s1), make(length(), s2)];
}
